// ── derived / legacy-compatible helpers ─────────────────────────────────────

/** Join an array field into a single readable line (used by older/simple UI). */
export function joinField(arr) {
  return Array.isArray(arr) ? arr.join(" · ") : (arr || "");
}

/** Given a PLAN_365 entry, return the 4 top-level "track" summaries the
 *  dashboard cards show: Learn, Practice, DSA, Project. */
export function dayTracks(plan) {
  if (!plan) return [];
  return [
    { key: "learn",    label: "LEARN",     content: joinField(plan.learn) },
    { key: "practice", label: "PRACTICE",  content: joinField(plan.practice) },
    { key: "dsa",      label: "DSA",       content: joinField(plan.dsaTopic) },
    { key: "project",  label: "PROJECT",   content: joinField(plan.project) },
  ];
}

/** Given a 1-based day number, return its Date. */
export function dateForDay(dayNum) {
  const start = new Date(PLAN_START_DATE + "T00:00:00");
  const d = new Date(start);
  d.setDate(d.getDate() + (dayNum - 1));
  return d;
}

/** The 1-based day number for "today" (may be <1 before start, or >365 after the plan ends). */
export function todayDayNum() {
  const start = new Date(PLAN_START_DATE + "T00:00:00");
  return Math.floor((new Date() - start) / 86400000) + 1;
}

/** Given a 1-based day number, return its PLAN_365 entry (or null if out of range). */
export function getPlanForDay(dayNum) {
  if (!dayNum || dayNum < 1 || dayNum > PLAN_365.length) return null;
  return PLAN_365[dayNum - 1];
}

/** Return the plan entry for a given calendar Date (or null if outside the plan). */
export function getDayPlan(date = new Date()) {
  const start = new Date(PLAN_START_DATE + "T00:00:00");
  const dayNum = Math.floor((date - start) / 86400000) + 1;
  return getPlanForDay(dayNum);
}

/** Return the plan entry for today. */
export function getTodayPlan() { return getDayPlan(new Date()); }

/** 0-based progress through the year (0.0 – 1.0). */
export function yearProgress() {
  const start = new Date(PLAN_START_DATE + "T00:00:00");
  const diff = Math.floor((new Date() - start) / 86400000);
  return Math.max(0, Math.min(1, diff / 365));
}

/** Human label for a volume + week, e.g. "Volume 2 · Week 6 — Arrays in Depth & Functional Programming" */
export function stageLabel(plan) {
  if (!plan) return "";
  return `Volume ${plan.volume} · Week ${plan.week} — ${plan.weekTitle}`;
}
